    /**
     * Finds a Stripe Customer ID based on the provided email address. Returns null if no customer is found.
     * @param {string} email
     * @see https://stripe.com/docs/api/customers/search
     *
     * @returns {Promise<string|null>} Stripe Customer ID, if found
     */
    async getCustomerIdByEmail(email) {
        await this._searchRateLimitBucket.throttle();
        try {
            const result = await this._stripe.customers.search({
                query: `email:"${email}"`,
                limit: 10,
                expand: ['data.subscriptions']
            });
            const customers = result.data;

            // No customer found, return null
            if (customers.length === 0) {
                return;
            }

            // Return the only customer found
            if (customers.length === 1) {
                return customers[0].id;
            }

            // Multiple customers found, find the one with the most recent subscription
            if (customers.length > 1) {
                const bestCustomer = this._findBestCustomerBySubscription(customers);
                return bestCustomer ? bestCustomer.id : null;
            }
        } catch (err) {
            debug(`getCustomerByEmail(${email}) -> ${err.type}:${err.message}`);
        }
    }

    /**
     * Find the customer with the most recent subscription among multiple customers.
     *
     * @param {Array<import('stripe').Stripe.Customer>} customers
     * @returns {import('stripe').Stripe.Customer|null}
     */
    _findBestCustomerBySubscription(customers) {
        let bestCustomer = null;
        let latestSubscriptionTime = 0;

        for (const customer of customers) {
            const mostRecentSubscriptionTime = this._getMostRecentSubscriptionTime(customer);

            if (mostRecentSubscriptionTime > latestSubscriptionTime) {
                latestSubscriptionTime = mostRecentSubscriptionTime;
                bestCustomer = customer;
            }
        }

        return bestCustomer;
    }

    /**
     * Get the most recent subscription end time for a customer.
     * @param {import('stripe').Stripe.Customer} customer
     * @returns {number} Unix timestamp in seconds; 0 if no valid subscriptions exist
     */
    _getMostRecentSubscriptionTime(customer) {
        if (!customer.subscriptions?.data?.length) {
            return 0;
        }

        return customer.subscriptions.data.reduce((latest, subscription) => {
            if (subscription.current_period_end && subscription.current_period_end > latest) {
                return subscription.current_period_end;
            }
            return latest;
        }, 0);
    }

