		function isAnonymousFunctionAssignmentException({
			left,
			operator,
			right,
		}) {
			if (
				left.type === "Identifier" &&
				["=", "&&=", "||=", "??="].includes(operator)
			) {
				const rhsType = right.type;

				if (rhsType === "ArrowFunctionExpression") {
					return true;
				}
				if (
					(rhsType === "FunctionExpression" ||
						rhsType === "ClassExpression") &&
					!right.id
				) {
					return true;
				}
			}
			return false;
		}

		/**
		 * Processes the collection of 'in' expression nodes to determine which reports should be excluded from being reported
		 * based on safety rules around 'in' expressions.
		 * @param {ASTNode} node The node representing the "for-in" initializer.
		 * @returns {void}
		 * @private
		 */
		function handleForInExpressionReports(node) {
			reportsBuffer.inExpressionNodes.forEach(
				inExpressionNode => processInExpressionNode(node, inExpressionNode),
			);
		}

		/**
		 * Processes a single `in` expression node and determines whether to exclude it from reporting.
		 * @param {ASTNode} initializerNode The initializer node whose children may contain 'in' expressions
		 * @param {ASTNode} inExpressionNode The 'in' expression to evaluate
