 * Helper extracted to reduce cognitive complexity of setOptions()
 * @param {Object} options
 * @param {Object} mongooseOptions
 * @param {string} key
 * @param {Function} sideEffectFn
 * @param {*} sideEffectArg
 * @api private
 */

function setMongooseOptionWithSideEffect(options, mongooseOptions, key, sideEffectFn, sideEffectArg) {
  if (key in options) {
    if (options[key] && !mongooseOptions[key]) {
      sideEffectFn(sideEffectArg);
    }
    mongooseOptions[key] = options[key];
